cd /dayjs && cat > test/tmp_tz.test.js <<'EOF'
import moment from 'moment-timezone'
import dayjs from '../src'
import utc from '../src/plugin/utc'
import timezone from '../src/plugin/timezone'
dayjs.extend(utc)
dayjs.extend(timezone)
const NY = 'America/New_York'
it('parse timestamp, js Date, Day.js object', () => {
  [1401638400000, new Date(1401638400000), dayjs(1401638400000)].forEach((input) => {
    const d = dayjs.tz(input, NY)
    const m = moment.tz(input, NY)
    console.log('dayjs:', d.format(), d.valueOf(), d.utcOffset(), '| moment:', m.format(), m.valueOf(), m.utcOffset())
    expect(d.format()).toBe('2014-06-01T12:00:00-04:00')
    expect(d.valueOf()).toBe(1401638400000)
    expect(d.utcOffset()).toBe(-240)
  })
})
it('still parses strings', () => {
  const d = dayjs.tz('2014-06-01 12:00', NY)
  expect(d.format()).toBe('2014-06-01T12:00:00-04:00')
  expect(d.valueOf()).toBe(1401638400000)
})
EOF
